import ast, json, sqlite3
from pathlib import Path
from types import SimpleNamespace
from forge_core.independent_review import _packet,_json,_hash,_review_messages,_review_reservation,REVIEW_SCHEMA
from forge_core.settings import Workspace
from forge_core.providers import ProviderGateway,ProviderConfig
from forge_core.runtime import ModelRequest
for level in ['L2','L3']:
 ws=next(Path.cwd().glob(f'.local/phase2/ws-20261115T020604Z-{level}-*'));db=ws/'data/forge.sqlite3';c=sqlite3.connect(db.as_uri()+'?mode=ro',uri=True);c.row_factory=sqlite3.Row;c.execute('BEGIN');row=c.execute('SELECT * FROM worker_runs').fetchone()
 out={'workspace':ws.name,'worker':{k:row[k] for k in ['id','node_key','state','token_spent','token_limit','tool_spent','tool_limit','steps','step_limit']}}
 try:
  packet=_packet(SimpleNamespace(workspace=Workspace.from_path(ws),path=str(db)),c,row,parse_diagnostics=True)
 except Exception as e:
  out.update(packet_error_type=type(e).__name__,packet_error=str(e))
 else:
  parsed=ast.parse(Path('backend/src/forge_core/independent_review.py').read_text());system=next(n.value for n in ast.walk(parsed) if isinstance(n,ast.Constant) and isinstance(n.value,str) and n.value.startswith('You are the independent reviewer of the CURRENT'))
  provider=ProviderGateway(ProviderConfig(id=row['provider_id'],kind='openai_compatible',base_url='https://example.invalid/v1',credential_ref='FORGE_PROVIDER_KEY_TEST',supports_json_schema=True,reasoning_effort='none',max_retries=0,timeout_seconds=120))
  req=ModelRequest(provider_id=row['provider_id'],model_id=row['model_id'],messages=_review_messages(packet,{'role':'system','content':system}),max_output_tokens=8192,max_retries=0,response_schema=REVIEW_SCHEMA,model_capabilities={'json_schema':True},model_capability_sources={'json_schema':'operator'})
  inp=len(json.dumps(provider._payload(req,False),ensure_ascii=False).encode())+64
  out.update(raw_packet_bytes=len(_json(packet).encode()),packet_sha256=_hash(packet),native_input_reserve=inp,context_limit=row['model_context_window'],remaining_budget=row['token_limit']-row['token_spent'],budget_after_input=row['token_limit']-row['token_spent']-inp,sections={k:len(_json(v).encode()) for k,v in packet.items()})
  try: out['reservation']=_review_reservation(provider,req,row,0)
  except Exception as e: out.update(reservation_error_type=type(e).__name__,reservation_error=str(e),reason_code=getattr(e,'code',None))
 print(json.dumps(out,ensure_ascii=False))
