            completed = []
            nodes = {node["key"]: node for node in data["nodes"]}
            for row in connection.execute("SELECT * FROM task_nodes WHERE plan_id=? AND status='succeeded'", (parent["id"],)):
                old_node = next(item for item in original["nodes"] if item["key"] == row["node_key"])
