                completed.append({"node_key": row["node_key"], "source_plan_id": parent["id"],
                    "source_revision": parent["revision"], "source_plan_digest": parent["digest"],
                    "run_id": run["id"], "worker_id": run["worker_id"], "evidence_refs": json.loads(row["evidence_refs"]),
                    "contract_sha256": digest(old_node)})
            if not completed:
                raise DomainError("Remaining DAG requires completed evidence to preserve")
            data["revision_lineage"] = {"version": "remaining-dag-v1", "parent_plan_id": parent["id"],
                "parent_revision": parent["revision"], "parent_digest": parent["digest"],
                "quest_goal_sha256": hashlib.sha256(quest["goal"].encode()).hexdigest(),
