                            row["plan_revision"],
                            row["tool_name"],
                            parameter_digest(parameters),
                            scope,
                            POLICY_VERSION,
                            call_id,
                        ),
                    ).fetchall()
                    return len(approvals) == 1 and datetime.fromisoformat(
                        approvals[0][0]
                    ) > datetime.now(UTC)
                return spec.risk == "R0"
            except (DomainError, ValueError, TypeError):
                return False

