        self,
        query,
        quest_ids=(),
        source_refs=(),
        limit=20,
        max_bytes=16384,
        connection=None,
        cursor=None,
        kinds=(),
        layers=(),
        created_after=None,
        created_before=None,
        source_types=(),
        exact_source_refs=False,
    ):
        """Read bounded indexed candidates, optionally only the exact source refs.

        Exact reads retain all source validity and filter checks, while suppressing
        lexical and Quest-based candidate expansion. They never substitute a
        similarly named source for an absent or invalid requested identity.
        """
        if not isinstance(query, str) or len(query.encode()) > 8192:
            raise ValueError("Invalid query")
        if not 1 <= limit <= 100 or not 0 <= max_bytes <= 65536:
            raise ValueError("Invalid recall bounds")
        if type(exact_source_refs) is not bool:
            raise ValueError("Invalid exact source selector")
        quests, refs = list(quest_ids), list(source_refs)
        kinds, layers = set(kinds), set(layers)
        source_types = set(source_types)
        if len(kinds) > 16 or len(layers) > 4:
            raise ValueError("Invalid recall filters")
        if len(source_types) > 16 or any(not isinstance(x, str) for x in source_types):
            raise ValueError("Invalid recall source filter")
        after = datetime.fromisoformat(created_after) if created_after else None
        before = datetime.fromisoformat(created_before) if created_before else None
        if any(value is not None and value.tzinfo is None for value in (after, before)):
            raise ValueError("Recall time filters must include timezone")
        if after and before and after > before:
            raise ValueError("Invalid recall time range")
        if (
            len(quests) > 32
            or len(refs) > 32
            or any(
                not isinstance(value, str) or not value or len(value) > 512
                for value in quests + refs
            )
        ):
            raise ValueError("Invalid recall selectors")
        if cursor is not None and (not isinstance(cursor, str) or len(cursor) > 600):
            raise ValueError("Invalid recall cursor")
        words = [] if exact_source_refs else _query_terms(" ".join([query, *quests, *refs]))
        if not words and not quests and not refs:
            return {"items": [], "omitted": 0, "bytes": 0, "cursor": None}
        items, used, omitted, next_cursor = [], 2, 0, None
        now = datetime.now(UTC)
        with self._connection(connection) as db:
            from .constraints import ConstraintService

            constraints = ConstraintService(self.store)
            # Bound each indexed range independently; a popular term cannot force
            # an unbounded DISTINCT/sort over the entire database.
            candidate_set = set()
            for word in words:
                candidate_set.update(
                    row[0]
                    for row in db.execute(
                        "SELECT ref FROM memory_terms WHERE term=? AND ref>? ORDER BY ref LIMIT 513",
                        (word, cursor or ""),
                    )
                )
            for quest_id in () if exact_source_refs else quests:
                candidate_set.update(
                    row[0]
                    for row in db.execute(
                        "SELECT source_ref FROM memory_source_index WHERE quest_id=? AND active=1 AND source_ref>? ORDER BY source_ref LIMIT 513",
                        (quest_id, cursor or ""),
                    )
                )
                if constraints.available(db):
                    candidate_set.update(
                        "constraint:" + row[0]
                        for row in db.execute(
                            """SELECT id FROM constraint_records WHERE quest_id=? AND status='active'
                            AND ('constraint:' || id)>? ORDER BY id LIMIT 513""",
                            (quest_id, cursor or ""),
                        )
                    )
            candidate_set.update(ref for ref in refs if ref > (cursor or ""))
            candidates = sorted(candidate_set)[:513]
            previous = cursor or ""
            for position, ref in enumerate(candidates[:512]):
                if len(items) >= limit:
                    omitted += len(candidates) - position
                    next_cursor = next_cursor or previous
                    break
                previous = ref
                item = None
                if ref.startswith(("constraint:", "message:")):
                    item = constraints.read_indexed(ref, connection=db)
                    if item is None:
                        continue
                elif ref.startswith("memory:"):
                    row = db.execute(
                        "SELECT id,statement,kind,layer,status,source_refs,created_at,valid_until,related_quest_ids,memory_key FROM memories WHERE id=?",
                        (ref[7:],),
                        created,
                        expiry,
                        raw_quests,
                        key,
                    ) = row
                    item_refs, item_quests = json.loads(raw_refs), json.loads(raw_quests)
                    if status == "invalid" or (expiry and datetime.fromisoformat(expiry) <= now):
                        continue
                    if any(
                        db.execute(
                            "SELECT 1 FROM revoked_memory_sources WHERE source_ref=?", (source,)
                        ).fetchone()
                        for source in item_refs
                    ):
                        continue
                    conflict = False
                    if key:
                        others = db.execute(
                            "SELECT statement,valid_until,source_refs FROM memories WHERE memory_key=? AND status!='invalid' AND id!=? LIMIT 101",
                            (key, ident),
                        ).fetchall()
                        conflict = len(others) > 100
                        for other_statement, other_expiry, other_refs in others[:100]:
                            if other_expiry and datetime.fromisoformat(other_expiry) <= now:
                                continue
                            if any(
                                db.execute(
                                    "SELECT 1 FROM revoked_memory_sources WHERE source_ref=?",
                                    (source,),
                                ).fetchone()
                                for source in json.loads(other_refs)
                            ):
                                continue
                            if other_statement != statement:
                                conflict = True
                                break
                    item = {
                        "id": ident,
                        "statement": statement,
                        "kind": kind,
                        "layer": layer,
                        "status": status,
                        "source_refs": item_refs,
                        "created_at": created,
                        "valid_until": expiry,
                        "related_quest_ids": item_quests,
                        "key": key,
                        "freshness": "unexpired" if expiry else "unknown",
                        "conflicted": conflict,
                    }
                else:
                    row = db.execute(
                        "SELECT source_hash,quest_id,plan_revision,source_type,trust,snapshot,active FROM memory_source_index WHERE source_ref=?",
                        (ref,),
                    ).fetchone()
                    if (
                        not row
                        or not row[6]
                        or db.execute(
                            "SELECT 1 FROM revoked_memory_sources WHERE source_ref=?", (ref,)
                        ).fetchone()
                    ):
                        continue
                    digest, quest_id, revision, source_type, trust, snapshot, _ = row
                    if hashlib.sha256(snapshot.encode("utf-8")).hexdigest() != digest:
                        continue
                    if trust == "core_workspace":
                        workspace = db.execute(
                            "SELECT id,root FROM workspace WHERE singleton=1"
                        ).fetchone()
                        if not workspace or json.loads(snapshot) != {
                            "id": workspace[0],
                            "root": workspace[1],
                        }:
                            continue
                        item = {
                            "id": ref,
                            "statement": f"workspace {workspace[0]}: {workspace[1]}",
                            "kind": "project",
                            "layer": "L2",
                            "status": "hypothesis",
                            "source_refs": [ref],
                            "created_at": None,
                            "valid_until": None,
                            "related_quest_ids": [],
                            "key": None,
                            "freshness": "current",
                            "conflicted": False,
                            "source_hash": digest,
                            "source_type": trust,
                        }
                    else:
                        item = None
                    if item is not None:
                        if not _kind_selected(item, kinds) or (
                            layers and item["layer"] not in layers
                        ):
                            continue
                        if source_types and item.get("source_type") not in source_types:
                            continue
                        if after or before:
                            # Workspace identity has no event timestamp and
                            # cannot satisfy a caller's bounded time range.
                            continue
                    continue
                if source_types and item.get("source_type") not in source_types:
                    continue
                if after or before:
                    try:
                        created = datetime.fromisoformat(item["created_at"])
                    except (TypeError, ValueError):
                        continue
                    if (
                        created.tzinfo is None
                        or (after and created < after)
                        or (before and created > before)
                    ):
                        continue
                size = len(
                    json.dumps(item, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
                ) + bool(items)
                if used + size > max_bytes:
                    omitted += 1
                    continue
                items.append(item)
                used += size
            if len(candidates) > 512:
                next_cursor = next_cursor or candidates[511]
                omitted += 1
        return {
            "items": items,
            "omitted": omitted,
            "bytes": used if items else 0,
            "cursor": next_cursor,
        }

