    elif fault == "missing_bound":
        wire["nodes"][0].pop("capacity_bounds")
    elif fault == "bool_bound":
        wire["nodes"][0]["capacity_bounds"]["max_delivery_bytes"] = True
    elif fault == "over_bound":
