    marker, texts = proof["marker"], proof["texts"]
    inserted = {item["projected_index"]: item for item in proof["insertions"]}
    entries = {item["projected_index"]: item for item in proof["entries"]}
    used, output = set(), []

    def restore_value(value):
        if isinstance(value, dict):
