tools.exec_command({cmd:"$source=Get-Content -LiteralPath .local/phase2/planner-v23-stage/capacity_preflight.py -Encoding UTF8; $source[200..390]; $source[500..626]; Get-Content -LiteralPath .local/phase2/planner-v23-stage/planner_input_roundtrip.py -Encoding UTF8; Get-Content -LiteralPath .local/phase2/planner-v23-stage/planner_resource_policy.py -Encoding UTF8",workdir:"D:\\Competition_this\\Agent",max_output_tokens:7000}),
tools.exec_command({cmd:"$source=Get-Content -LiteralPath .local/phase2/planner-v23-stage/quest_graph.py -Encoding UTF8; $source[1190..1470]; Get-Content -LiteralPath backend/src/forge_core/budget_policy.py -Encoding UTF8 -TotalCount 250; Get-Content -LiteralPath backend/src/forge_core/composer_resources.py -Encoding UTF8 -TotalCount 200",workdir:"D:\\Competition_this\\Agent",max_output_tokens:8500})
