        run = work.connection.execute(
            "SELECT * FROM worker_runs WHERE quest_id=? AND plan_id=? AND node_key=? AND worker_id=? AND state IN ('review_pending','succeeded') AND execution_mode='live' ORDER BY created_at DESC LIMIT 1",
