    plan = connection.execute(
        "SELECT graph_json FROM quest_plans WHERE id=?", (run["plan_id"],)
    ).fetchone()
    declared_policy = (
        (json.loads(plan[0]).get("capacity_contract") or {}).get("input_acquisition_policy")
