                    "actual_bytes": len(raw),
                }
            )
    executable = [
        {"path": file.relative_to(REPO).as_posix(), "sha256": sha(file.read_bytes())}
        for file in sorted(
            set((REPO / "backend/src").rglob("*.py"))
            | set((REPO / "backend/scripts/phase2").rglob("*.py"))
        )
    ]
    result = {
