"""Explicit model-selected capacity profiles; exact decoding to the V23 contract."""

from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from .graph_domain import CapabilityWire, _strict_wire_schema
from .planner_dataflow import DataflowDependencyWire
from .planner_dataflow_v23 import DataflowGraphWireV23, DataflowNodeWireV23, DataflowVerifierWireV23

OUTPUT_PROFILES = {
    "inline_1536": (1, 1536),
    "inline_2048": (1, 2048),
    "artifact_2048_delivery_1536": (2048, 1536),
    "artifact_3072_delivery_1536": (3072, 1536),
}
ACTION_PROFILES = {
    "declared_sources_only_0": 0,
    "small_receipts_1024": 1024,
    "bounded_test_receipts_4096": 4096,
}


class ProfileModel(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True, json_schema_extra=_strict_wire_schema)


class OutputProfile(ProfileModel):
    profile: Literal[
        "inline_1536",
        "inline_2048",
        "artifact_2048_delivery_1536",
        "artifact_3072_delivery_1536",
    ] = Field(description="Choose only when the entire assigned result fits. Inline creates no artifact; otherwise choose sufficient custom bounds. No default.")

    def bounds(self):
        artifact, delivery = OUTPUT_PROFILES[self.profile]
        return {"max_artifact_bytes": artifact, "max_delivery_bytes": delivery}


class CustomOutputProfile(ProfileModel):
    profile: Literal["custom"]
    max_artifact_bytes: int = Field(ge=1, le=32768)
    max_delivery_bytes: int = Field(ge=1, le=32768)

    def bounds(self):
        return self.model_dump(exclude={"profile"})


class ActionProfile(ProfileModel):
    profile: Literal[
        "declared_sources_only_0", "small_receipts_1024", "bounded_test_receipts_4096"
    ] = Field(description="New receipt output beyond complete declared initial sources: 0 for inline declared-source analysis, 1024 for small receipts, 4096 for bounded numeric/test receipts, or sufficient custom. No tool authority or default.")

    def allowance(self):
        return ACTION_PROFILES[self.profile]


class CustomActionProfile(ProfileModel):
    profile: Literal["custom"]
    action_evidence_allowance_bytes: int = Field(ge=0, le=32768)

    def allowance(self):
        return self.action_evidence_allowance_bytes


OutputCapacity = Annotated[OutputProfile | CustomOutputProfile, Field(discriminator="profile")]
ActionEvidence = Annotated[ActionProfile | CustomActionProfile, Field(discriminator="profile")]


class DataflowNodeWireV25(ProfileModel):
    key: str = Field(min_length=1, max_length=100, pattern=r"^[A-Za-z0-9_-]+$")
    objective: str = Field(min_length=1, max_length=2000)
    success_criteria: list[DataflowVerifierWireV23] = Field(min_length=1, max_length=5)
    required_capabilities: list[CapabilityWire]
    expected_artifact: str | None = Field(max_length=2000)
    max_attempts: int = Field(ge=1, le=10)
    allowed_tools: list[str] = Field(max_length=32)
    verified_input_paths: list[str] = Field(max_length=32)
    predecessors: list[DataflowDependencyWire] = Field(max_length=8)
    output_capacity: OutputCapacity
    action_evidence: ActionEvidence

    def v23_data(self):
        value = self.model_dump(exclude={"output_capacity", "action_evidence"})
        value["capacity_bounds"] = {
            **self.output_capacity.bounds(),
            "action_evidence_allowance_bytes": self.action_evidence.allowance(),
        }
        return value

    @model_validator(mode="after")
    def exact_semantics(self):
        if isinstance(self.output_capacity, OutputProfile):
            inline = self.output_capacity.profile.startswith("inline_")
            if inline != (self.expected_artifact is None):
                raise ValueError("capacity_profile_must_match_explicit_artifact_contract")
        DataflowNodeWireV23.model_validate(self.v23_data())
        return self


class DataflowGraphWireV25(ProfileModel):
    allocation_mode: Literal["core_measured"]
    nodes: list[DataflowNodeWireV25] = Field(min_length=1, max_length=8)

    def decoded(self):
        return DataflowGraphWireV23.model_validate(
            {"allocation_mode": self.allocation_mode, "nodes": [node.v23_data() for node in self.nodes]}
        )

    def proposal_data(self, **kwargs):
        graph = self.decoded().proposal_data(**kwargs)
        graph["capacity_contract"]["planner_capacity_choices"] = {
            node.key: {
                "output_capacity": node.output_capacity.model_dump(),
                "action_evidence": node.action_evidence.model_dump(),
            }
            for node in self.nodes
        }
        return graph
"""Bounded complete V25 diagnostics; explicit profile decode never alters a choice."""

import copy
import json

from pydantic import ConfigDict, create_model

from .domain import DomainError
from .planner_capacity_preview_v23 import _preview_complete_capacity
from .planner_dataflow_v25 import DataflowNodeWireV25
from .planner_guidance_v24 import preview_sources_v23
from .planner_source_preview import MAX_RESPONSE_BYTES

ProjectionNode = create_model(
    "PlannerV25ProfileSourceProjection",
    __config__=ConfigDict(extra="forbid", strict=True),
    **{
        name: (field.annotation, copy.deepcopy(field))
        for name, field in DataflowNodeWireV25.model_fields.items()
        if name != "success_criteria"
    },
)

NODE_COLUMNS = [
    "profile_id", "artifact_bytes", "delivery_bytes", "action_evidence_bytes",
    "known_source_bytes", "future_source_bytes", "source_bound_bytes",
    "raw_packet_bound", "raw_headroom", "review_input", "review_headroom",
    "correction_input", "correction_headroom", "initial_work_tokens",
    "review_cycle_reserve_tokens", "minimum_node_tokens", "policy_cycle_calls", "violations",
]


def decoded_response(raw_response):
    """Decode valid profile/source fields while retaining invalid original criteria."""
    if not isinstance(raw_response, str) or len(raw_response.encode()) > MAX_RESPONSE_BYTES:
        raise ValueError("response_outside_projection_bound")
    raw = json.loads(raw_response)
    if not isinstance(raw, dict) or set(raw) != {"allocation_mode", "nodes"} or raw["allocation_mode"] != "core_measured" or not isinstance(raw["nodes"], list) or not 1 <= len(raw["nodes"]) <= 8:
        raise ValueError("invalid_profile_projection")
    nodes = []
    for node in raw["nodes"]:
        if not isinstance(node, dict) or set(node) - DataflowNodeWireV25.model_fields.keys():
            raise ValueError("invalid_profile_node_fields")
        projected = ProjectionNode.model_validate({key: value for key, value in node.items() if key != "success_criteria"})
        if projected.output_capacity.profile != "custom":
            inline = projected.output_capacity.profile.startswith("inline_")
            if inline != (projected.expected_artifact is None):
                raise ValueError("capacity_profile_must_match_explicit_artifact_contract")
        decoded = projected.model_dump(exclude={"output_capacity", "action_evidence"})
        decoded["success_criteria"] = node.get("success_criteria")
        decoded["capacity_bounds"] = {
            **projected.output_capacity.bounds(),
            "action_evidence_allowance_bytes": projected.action_evidence.allowance(),
        }
        nodes.append(decoded)
    return json.dumps({"allocation_mode": "core_measured", "nodes": nodes}, ensure_ascii=False)


def compact_report(report):
    """All nodes remain explicit; two candidate numeric rows are bounded per node."""
    nodes = []
    for node in report["nodes"]:
        if node["status"] != "available":
            nodes.append({"node": node["node"], "status": node["status"], "reason": node["reason"]})
            continue
        rows = []
        for item in node["candidates"]:
            bounds = item["declared_bounds"]
            rows.append([
                item["profile_id"], bounds["max_artifact_bytes"], bounds["max_delivery_bytes"],
                item["action_evidence_allowance_bytes"], item["known_source_bytes"],
                item["future_source_bytes_bound"], bounds["max_source_receipt_bytes"],
                item["raw_packet_bound"], item["raw_packet_headroom_bytes"],
                item["review_input_bound"], item["native_review_headroom"],
                item["correction_input_bound"], item["native_correction_headroom"],
                item["initial_work_tokens"], item["review_cycle_reserve_tokens"],
                item["minimum_node_tokens"], item["policy_cycle_calls"], item["violations"],
            ])
        nodes.append({"node": node["node"], "status": "available", "rows": rows, "omitted_candidates": node["omitted_candidates"], "unmeasurable_candidates": node["unmeasurable_candidates"]})
    return {
        "version": "planner-capacity-preview-v25", "status": "available",
        "scope": "diagnostic_only_original_profiles_and_formulas_no_allocation_or_authority",
        "columns": NODE_COLUMNS, "nodes": nodes,
        "aggregate_policy_projection": report["aggregate_policy_projection"],
        "preserved_completed_keys": report["preserved_completed_keys"],
    }


def preview_complete_capacity_v25(*args, **kwargs):
    try:
        service, quest, raw, inventory, provider = args
        return _preview_complete_capacity(
            service, quest, decoded_response(raw), inventory, provider,
            _report_transform=compact_report, **kwargs,
        )
    except (OSError, KeyError, TypeError, ValueError, RecursionError, DomainError):
        return {"version": "planner-capacity-preview-v25", "status": "unavailable", "reason": "invalid_profile_or_complete_measurement"}


def preview_sources_v25(store, raw_response, inventory, **kwargs):
    try:
        return preview_sources_v23(store, decoded_response(raw_response), inventory, **kwargs)
    except (OSError, KeyError, TypeError, ValueError, RecursionError, DomainError):
        return {"version": "planner-source-preview-v25", "status": "unavailable", "reason": "invalid_profile_source_projection"}
# V25 explicit capacity choices — read-only proposal

V24 actual results remain failed. Its long guidance did not change the initial model's preference for 8–16 KiB inline deliveries or concentrating complete inventory in the first research node. A valid JSON proposal is not a feasible proposal. L1 repair passed local envelopes but exceeded actual residual Worker allocation by 1,594 tokens; the schema must therefore make a compact complete contract an explicit decision before the first request, while retaining custom declarations.

## Minimal wire change

Introduce `semantic_protocol_version=v25` and an isolated `DataflowGraphWireV25`; preserve V23 parsing and semantics exactly. Replace the V25 node's raw `capacity_bounds` with two explicit, independently selected discriminated unions:

| Choice | Explicit profile | Exact decoded values |
| --- | --- | --- |
| output_capacity | inline_1536 | artifact 1, delivery 1536 |
| output_capacity | inline_2048 | artifact 1, delivery 2048 |
| output_capacity | artifact_2048_delivery_1536 | artifact 2048, delivery 1536 |
| output_capacity | artifact_3072_delivery_1536 | artifact 3072, delivery 1536 |
| output_capacity | custom | required max_artifact_bytes and max_delivery_bytes, original integer range 1–32768 |
| action_evidence | declared_sources_only_0 | allowance 0 |
| action_evidence | small_receipts_1024 | allowance 1024 |
| action_evidence | bounded_test_receipts_4096 | allowance 4096 |
| action_evidence | custom | required action_evidence_allowance_bytes, original integer range 0–32768 |

Every selection is mandatory. No default profile, fallback, inference from tools or automatic replacement after rejection. Decode the exact model-selected tuple into the existing validated V23 graph and retain the original choice in proposal provenance. A custom tuple is still allowed to be infeasible; it must be rejected under unchanged measurement. No scenario ID, source filename, task answer or fixed DAG appears in the decoder or profile selection policy.

The JSON Schema descriptions should make the decision local and short: choose a compact profile only if it holds the entire assigned output; inline profiles do not claim a file; artifact profiles need an explicit expected_artifact and the same node's existing create/revise tools; action evidence covers new receipt output beyond complete declared initial reads, not output tokens or artifact body. The model remains responsible for adequate bounds and all semantic requirements. Use two unions rather than one coupled profile so an artifact does not implicitly grant or price a numeric action.

## Source and scheduling decisions remain semantic

Output profiles cannot by themselves fix source concentration. Present exact per-file canonical receipt sizes and a concise generic responsibility procedure: assign each task-required original source to the specialist that examines it; carry all still-needed conclusions and exact citations in a complete immediate predecessor delivery; only request extra ancestors/originals when independent assessment needs them. Preserve user-requested specializations and independent assessment; never force a chain when parallel work is required.

The model chooses paths, handoffs, control edges and specialization. Core's existing strict-success-chain detection selects the unchanged serial capacity arithmetic only after that semantic graph is valid. Every extra edge and every selected ancestor handoff remains visible and priced. The decoder never redistributes files or removes redundant-looking edges. An oversized all-source research node is a valid failed model decision, not permission for Core to split it.

## Compact complete diagnostics

Current complete-capacity reports can exceed 8192 bytes because all 20+ numeric fields repeat for every node/candidate. Preserve the cap and avoid an all-or-nothing unavailable result by defining one compact V25 representation with an explicit column dictionary and one numeric row per node. Include every up-to-eight node; no hidden omission or prefix truncation.

Required per-node fields: key, profile_id, exact selected A/D/E, known-source bytes, future-source bound, total-source bound, raw bound/headroom, native review input/headroom, native correction input/headroom, complete initial-work tokens, review/correction reserve, policy cycle calls, projected node budget and violation codes. Preserve all semantic errors separately; an invalid criterion is unmeasured, never silently replaced.

Use compact per-node source contribution rows `[kind, producer_or_path, declared_bound, measured_bytes]` with a shared schema. Preserve all declared source identities/counts or return an explicit bounded-source overflow diagnostic; do not include source bodies/objectives. Inventory-owner mapping and unselected paths are descriptive only. The original selected full source remains in actual measurement and runtime.

Aggregate: detected shape, original ceiling, current residual before repair, future coordination reserve, all node baselines, one serial reserve or independent-cycle totals, complete projected total and remaining headroom. Label projections as first-pass measurement, not approval or feasibility. Native fixed-point sizing and residual recheck remain decisive after the model's single allowed repair.

Diagnostics should be model-readable before repair without reproducing verbose suggestion prose per node. Keep full detailed diagnostics in the durable rejection event if needed, but send a bounded compact view with every node's essential metrics; missing extra detail must be declared, never treated as a pass. Do not increase the two-call Planner budget to introduce a separate measuring dialogue. A read-only capacity tool would need an explicitly bounded protocol redesign and additional ledger accounting; it is a larger alternative, not the minimal change.

## Owned implementation and tests after freeze release

- New `planner_dataflow_v25.py`: strict explicit unions and exact decoder; no production defaults or sample solution.
- `quest_graph.py`: V25 wire selection, concise profile policy, one unchanged repair round; preserve V23.
- New `planner_capacity_preview_v25.py` or compact view helper: complete <=8-node measurement and aggregate, no provider calls or writes.
- `forge_api/main.py`: background Planner chooses V25; API output remains the same approved graph format.
- Focused tests: all profile combinations decode exactly; custom preserves every integer; missing/unknown/mixed profiles, bool values and incompatible artifact choices reject; V23 unchanged; no semantic field/path/edge edits; invalid criteria remain invalid; eight nodes with maximum-length legal identifiers stay within original diagnostic bound with all rows present; original Router L1/L2/L3 full requests and repair fit 24000/65536; actual residual after Planner charges still enforced; one rejection and one repair remain exactly two calls; no tool/Provider execution from previews.

The existing constructed V23 fixture supports offline feasibility only. Do not put its source assignments, outputs or DAG into production prompts. After implementation, freeze a new source manifest and run unchanged full regression and actual L1/L2/L3; no claim that enum selection guarantees the model will choose a sufficient feasible plan.

