"""Fresh in-memory SQL provenance fixtures; no runtime database or Provider."""

import copy
import importlib.util
import sqlite3
from pathlib import Path
from types import SimpleNamespace

import pytest

spec = importlib.util.spec_from_file_location(
    "memory_source_fixture_auditor", Path(__file__).with_name("audit_memory_version.py")
)
audit = importlib.util.module_from_spec(spec)
spec.loader.exec_module(audit)


@pytest.fixture
def fixture():
    db = sqlite3.connect(":memory:")
    db.row_factory = sqlite3.Row
    db.executescript(
        "CREATE TABLE messages(id,conversation_id,role,content,metadata,created_at);"
        "CREATE TABLE memories(id,statement,kind,layer,status,source_refs,created_at,valid_until,related_quest_ids,memory_key);"
        "CREATE TABLE revoked_memory_sources(source_ref);"
    )
    prompt = "Read inputs/aster-release.json. For Aster use failed zero and unit plus integration at least 15."
    user = {"id": "source-user", "conversation_id": "main", "role": "user", "content": prompt, "metadata": "{}", "created_at": "2026-01-01T00:00:00+00:00"}
    db.execute("INSERT INTO messages VALUES (?,?,?,?,?,?)", tuple(user.values()))
    eligible = {}
    for identity, statement in (("path-memory", "Read inputs/aster-release.json"), ("rule-memory", "For Aster use failed zero and unit plus integration at least 15")):
        row = {"id": identity, "statement": statement, "kind": "constraint", "layer": "L1", "status": "hypothesis", "source_refs": '["message:source-user"]', "created_at": "2026-01-01T00:00:01+00:00", "valid_until": None, "related_quest_ids": '["source-quest"]', "memory_key": identity}
        db.execute("INSERT INTO memories VALUES (?,?,?,?,?,?,?,?,?,?)", tuple(row.values()))
        item = {"id": identity, "statement": statement, "kind": "constraint", "layer": "L1", "status": "hypothesis", "source_refs": ["message:source-user"], "created_at": row["created_at"], "valid_until": None, "related_quest_ids": ["source-quest"], "key": identity, "freshness": "unknown", "conflicted": False}
        eligible["memory:" + identity] = {"item": item, "item_sha256": audit.sha(audit.canonical(item)), "raw": {"table": "memories", "row": row, "row_sha256": audit.sha(audit.canonical(row))}}
    record = {"quest_ids": ["source-quest", "target-quest"], "original_spec": {"first_prompt": prompt}, "source_snapshot_before": {"original_user": user, "eligible": eligible}, "source_snapshot_pre_compaction": {"eligible": copy.deepcopy(eligible)}, "source_snapshot_after_router": {"eligible": copy.deepcopy(eligible)}}
    result = {"retrieved_source_ids": ["path-memory", "rule-memory"]}

    def scoped(text):
        return all(value in text for value in ("inputs/aster-release.json", "Aster", "failed", "zero", "unit", "integration", "15"))

    yield db, record, result, SimpleNamespace(scoped_rule=scoped)
    db.close()


def collect(fixture):
    db, record, result, driver = fixture
    db.commit()
    db.execute("PRAGMA query_only=ON")
    db.execute("BEGIN")
    before = db.total_changes
    proofs = audit.memory_source_proofs(db, record, result, driver)
    assert db.total_changes == before
    assert not db.execute("PRAGMA database_list").fetchone()[2]
    return proofs


def test_separate_same_source_path_and_rule_form_one_bounded_proof(fixture):
    proofs = collect(fixture)
    assert len(proofs) == 2 and all(item["passed"] for item in proofs)
    assert {item["item_id"] for item in proofs} == {"path-memory", "rule-memory"}
    assert {item["original_user_message_id"] for item in proofs} == {"source-user"}


@pytest.mark.parametrize("selected", [["path-memory"], ["rule-memory"], []])
def test_incomplete_retrieved_rule_or_path_cannot_prove_reuse(fixture, selected):
    fixture[2]["retrieved_source_ids"] = selected
    assert collect(fixture) == []


@pytest.mark.parametrize("field,value", [("status", "verified"), ("conflicted", True), ("valid_until", "2000-01-01T00:00:00+00:00"), ("related_quest_ids", ["target-quest"]), ("id", "another-id")])
def test_tampered_hypothesis_item_is_not_eligible(fixture, field, value):
    saved = fixture[1]["source_snapshot_before"]["eligible"]["memory:rule-memory"]
    saved["item"][field] = value
    saved["item_sha256"] = audit.sha(audit.canonical(saved["item"]))
    assert collect(fixture) == []


def test_revoked_original_user_source_invalidates_both_memories(fixture):
    fixture[0].execute("INSERT INTO revoked_memory_sources VALUES (?)", ("message:source-user",))
    assert collect(fixture) == []


def test_source_row_changes_after_snapshot_are_not_hidden_by_saved_hash(fixture):
    fixture[0].execute("UPDATE memories SET statement='changed' WHERE id='rule-memory'")
    assert collect(fixture) == []


def test_source_snapshot_changes_after_router_cannot_be_used(fixture):
    fixture[1]["source_snapshot_after_router"]["eligible"].pop("memory:rule-memory")
    assert collect(fixture) == []


def test_memory_key_conflict_fails_closed(fixture):
    fixture[0].execute("INSERT INTO memories SELECT 'conflict', 'disagree', kind,layer,status,source_refs,created_at,valid_until,related_quest_ids,memory_key FROM memories WHERE id='rule-memory'")
    assert collect(fixture) == []


def test_original_user_row_change_is_detected(fixture):
    fixture[0].execute("UPDATE messages SET content='changed' WHERE id='source-user'")
    with pytest.raises(ValueError, match="original_user_binding"):
        collect(fixture)
